const item = $input.first().json;
const headers = item.headers ?? {};
const body = item.body ?? item;
const receivedToken = headers['x-workflow-token'] ?? headers['X-Workflow-Token'];
if (!receivedToken || receivedToken !== $env.N8N_WORKFLOW_TOKEN) {
  throw new Error('Invalid x-workflow-token');
}
if (body.trigger !== 'lead.reply_draft_requested') {
  throw new Error(`Unexpected trigger: ${body.trigger ?? 'missing'}`);
}
if (!body.lead_id) {
  throw new Error('Missing lead_id');
}
if (!body.agent_run_id) {
  throw new Error('Missing agent_run_id');
}
return [{ json: { trigger: body.trigger, lead_id: body.lead_id, agent_run_id: body.agent_run_id } }];

const context = $input.first().json;
const triggerPayload = $('Validate Trigger').first().json;
const lead = context.lead ?? {};
const agentRunId = context.agent_run?.id ?? context.agent_run_id ?? triggerPayload.agent_run_id;
const pricing = Array.isArray(context.pricing_templates) ? context.pricing_templates : [];
const text = [lead.company_name, lead.contact_name, lead.contact_email, lead.enquiry_text].filter(Boolean).join(' ').toLowerCase();
const matches = pricing.filter((template) => [template.service, template.category, template.description].filter(Boolean).join(' ').toLowerCase().split(/\s+/).filter((token) => token.length > 3).some((token) => text.includes(token))).slice(0, 2);
const selected = (matches.length > 0 ? matches : pricing).slice(0, 2);
const firstName = lead.contact_name?.split(/\s+/)[0] ?? 'there';
const services = selected.map((template) => template.service).filter(Boolean).join(', ') || 'CRM and growth support';
const company = lead.company_name ?? 'your team';
const fallback = {
  lead_id: lead.id ?? triggerPayload.lead_id,
  agent_run_id: agentRunId,
  draft_message: [`Hi ${firstName},`, '', `Thanks for reaching out to Fimmick about ${services}. We can help map the opportunity, clarify the best-fit scope, and recommend a practical next step for ${company}.`, '', 'Would you be open to a short discovery call this week so we can confirm goals, timeline, and budget range before we propose the right package?', '', 'Best,', 'Fimmick ClientOps'].join('\n'),
  context_summary: `Fallback reply drafted for ${company}.`,
  confidence_score: 0.62,
  risk_notes: ['Generated by deterministic-fallback; review tone and commercial claims before sending.']
};
const model = $env.OPENROUTER_MODEL || 'anthropic/claude-sonnet-4-6';
const openrouter_request = {
  model,
  messages: [
    { role: 'system', content: 'Return only JSON matching the ClientOps draft reply writeback contract. Do not include markdown.' },
    { role: 'user', content: JSON.stringify({ context, required_fields: ['lead_id', 'agent_run_id', 'draft_message', 'context_summary', 'confidence_score', 'risk_notes'] }) }
  ],
  response_format: { type: 'json_object' }
};
return [{ json: { context, fallback, openrouter_request, openrouter_configured: Boolean($env.OPENROUTER_API_KEY) } }];

const prepared = $('Prepare Fallback / AI Request').first().json;
const fallback = prepared.fallback;
const response = $input.first()?.json ?? {};

function parsePayload(value) {
  const content = value.choices?.[0]?.message?.content;
  if (typeof content === 'string') {
    try {
      return JSON.parse(content);
    } catch (error) {
      return undefined;
    }
  }
  return isPlainObject(content) ? content : undefined;
}

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function finiteNumber(value, fallbackValue) {
  const number = typeof value === 'number' ? value : Number(value);
  return Number.isFinite(number) ? number : fallbackValue;
}

function clampNumber(value, fallbackValue, min, max) {
  return Math.min(max, Math.max(min, finiteNumber(value, fallbackValue)));
}

function safeString(value, fallbackValue, maxLength = 8000) {
  return typeof value === 'string' && value.trim() ? value.trim().slice(0, maxLength) : fallbackValue;
}

function safeStringArray(value, fallbackValue) {
  if (!Array.isArray(value) || value.some((entry) => typeof entry !== 'string')) {
    return fallbackValue;
  }
  return value.map((entry) => entry.trim()).filter(Boolean).slice(0, 10);
}

const parsed = parsePayload(response);
const output = {
  lead_id: fallback.lead_id,
  agent_run_id: fallback.agent_run_id,
  draft_message: safeString(parsed?.draft_message, fallback.draft_message),
  context_summary: safeString(parsed?.context_summary, fallback.context_summary, 1200),
  confidence_score: clampNumber(parsed?.confidence_score, fallback.confidence_score, 0, 1),
  risk_notes: safeStringArray(parsed?.risk_notes, fallback.risk_notes),
};
return [{ json: output }];
